class BosPanel extends HTMLElement {
  connectedCallback() {
    const root = this.attachShadow({ mode: 'open' });
    root.innerHTML = `
      <section>
        <h2>Panel</h2>
        <label for="shadow-name">Nickname</label>
        <input id="shadow-name" name="nickname" type="text">
        <button id="shadow-save" type="button">Save nickname</button>
        <bos-badge></bos-badge>
      </section>`;
    const badge = root.querySelector('bos-badge');
    const nested = badge.attachShadow({ mode: 'open' });
    nested.innerHTML = `<a id="shadow-help" href="/shadow/help">Help</a>`;
  }
}
customElements.define('bos-panel', BosPanel);

